<?php if(promo_ready()): ?><section class="panel"><h2>Email-only welcome codes</h2><p>Settings above apply to future email claims. Issued codes retain their percentage and expiry. No account or password is required. Unpaid orders reserve codes; payment or completed delivery finalizes use. An unpaid cancellation releases the code before expiry.</p><p>Email delivery and ownership verification are not configured. Entering an email does not prove ownership.</p><a class="button" href="/admin/offers?tab=codes&amp;kind=welcome">Manage welcome codes</a></section><?php return;endif ?>
<?php
query("UPDATE welcome_promotions SET status='expired',reason='time_elapsed' WHERE status='active' AND expires_at<=?",[welcome_now()]);
$welcomeStats=rows('SELECT status,COUNT(*) AS quantity FROM welcome_promotions GROUP BY status');$counts=['active'=>0,'redeemed'=>0,'expired'=>0];foreach($welcomeStats as $stat)$counts[$stat['status']]=(int)$stat['quantity'];
?>
<section class="panel"><h2>Welcome offer activity</h2><p>Settings above apply to future registrations. Issued offers keep their original percentage and expiry. Redemptions remain used if an order is cancelled.</p><div class="stat-grid"><?php foreach($counts as $status=>$quantity): ?><article class="stat-card"><span><?= e(ucfirst($status)) ?></span><strong><?= $quantity ?></strong></article><?php endforeach ?></div></section>
<div class="panel table-scroll"><table><thead><tr><th>Customer</th><th>Offer</th><th>Status</th><th>Activated / expires (UTC)</th><th>Redemption</th></tr></thead><tbody><?php foreach(rows('SELECT w.*,u.name,u.email,o.reference,o.currency FROM welcome_promotions w JOIN users u ON u.id=w.user_id LEFT JOIN orders o ON o.id=w.redeemed_order_id ORDER BY w.activated_at DESC LIMIT 200') as $issued): ?><tr><td><?= e($issued['name']) ?><small><?= e($issued['email']) ?></small></td><td><?= (int)$issued['percentage'] ?>%</td><td><span class="status-tag"><?= e(ucfirst($issued['status'])) ?></span></td><td><?= e($issued['activated_at']) ?><small><?= e($issued['expires_at']) ?></small></td><td><?php if($issued['reference']): ?><a class="text-link" href="/admin/orders?view=<?= e($issued['redeemed_order_id']) ?>"><?= e($issued['reference']) ?></a><small><?= e($issued['currency']) ?> <?= number_format($issued['discount_amount']/100,2) ?> · <?= e($issued['redeemed_at']) ?> UTC</small><?php else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table><p class="muted">Shows the latest 200 offers. Complete history remains in the database.</p></div>
